const icon = (glyph: string, color: string): NerdIcon => ({ char: String.fromCodePoint(GLYPHS[glyph]), color });
const index = (rows, column: number, make) => {
	const found: Record<string, NerdIcon> = {};
	for (const [id, row] of Object.entries(rows)) for (const key of row[column].split(" ").filter(Boolean)) found[key] = make(id, row);
	return found;
};
const fileIcon = (_id: string, [glyph, color]) => icon(glyph, color);

export const file = fileIcon("", FILES["document"]);
export const folder = icon("cod-folder", FOLDERS["folder"][0]);
export const folderOpen = icon("cod-folder_opened", FOLDERS["folder"][0]);
export const byFileName = index(FILES, 2, fileIcon);
export const byExtension = index(FILES, 3, fileIcon);
export const byFolderName = index(FOLDERS, 1, (_id, [color]) => icon("cod-folder", color));
export const byFolderNameOpen = {
	...index(FOLDERS, 1, (_id, [color]) => icon("cod-folder_opened", color)),
	...index(FOLDERS, 2, (_id, [color]) => icon("cod-folder_opened", color)),
};

/** The icon of a file or folder named `name` (no path): exact name, longest extension, default. */
export function nerdIcon(name: string, { isDirectory = false, open = false } = {}): NerdIcon {
	const lower = String(name).toLowerCase();
	if (isDirectory) return (open ? byFolderNameOpen[lower] || folderOpen : byFolderName[lower] || folder);
	if (byFileName[lower]) return byFileName[lower];
	// "a.test.ts" tries "test.ts", then "ts"; ".eslintrc.json" tries "eslintrc.json", then "json".
	for (let dot = lower.indexOf("."); dot >= 0; dot = lower.indexOf(".", dot + 1)) {
		const found = byExtension[lower.slice(dot + 1)];
		if (found) return found;
	}
	return file;
}
